// 再評価の確定証跡から、旧指摘との照合表・対応方針・画像付きレポートを生成する。
import fs from 'node:fs';
import assert from 'node:assert/strict';
import crypto from 'node:crypto';
const out='artifacts/responsive-reevaluation-20260913';
const read=f=>JSON.parse(fs.readFileSync(`${out}/${f}`,'utf8'));
const manifest=read('manifest.json'),survey=read('survey.json'),confirm=read('confirm.json'),flows=read('flows.json'),reading=read('reading-final.json');
