const table=(heads,rows)=>`| ${heads.join(' | ')} |\n|${heads.map(()=>'---').join('|')}|\n${rows.map(r=>'| '+r.join(' | ')+' |').join('\n')}`;
let md=`# レスポンシブ再評価レポート\n\n2026-09-13\n\n${intro}\n\n${correction}\n\n## 検証計画と対象\n\n${method}\n\n${environment}\n\n[事前計画](PLAN.md) / [対象版のSHA-256](manifest.json)\n\n${table(['確認軸','今回の範囲'],coverage)}\n\n## 問題一覧と対応方針\n\n${table(['ID','重要度','問題','再現条件'],issues.map(i=>[i.id,i.severity,i.title,i.conditions]))}\n\n`;
for(const i of issues){md+=`### ${i.id} · ${i.title}\n\n重要度: ${i.severity}。${i.conditions}\n\n${i.finding}\n\n原因/配置上の要因: ${i.cause}\n\n対応方針: ${i.fix}\n\n受入条件: ${i.accept}\n\n![${i.id} 確認画面](${i.image})\n\n[補足画面](${i.extra}) · [計測/操作結果](${i.evidence})\n\n`;}
md+=`## 旧9件との照合\n\n${table(['旧ID','旧重要度','元の問題','現在の評価','根拠'],old)}\n\n## 修正方針と提出準備\n\n${next}\n\n${submission}\n\n## 限界・証跡の扱い\n\n${caveat}\n\n64枚の探索画像はすべてを最終画面として合格にしたものではありません。演出完了後の再確認は confirmed- / final- 画像、confirm.json / reading-final.json を優先してください。flows.json の試行中の3件失敗は、非表示リンクや曖昧なセレクターを拾ったテスト側の問題で、確定確認で解消。入口の accepted:false は閉鎖アニメーション完了前の測定で、閉鎖まで待って再確認しています。reading.json の読込前API参照例外も reading-final.json で修正・再確認済みです。以前のレポート・失敗証跡は削除していません。\n\n[探索結果](survey.json) / [連続操作の試行記録](flows.json) / [確定確認](confirm.json) / [可読領域の確定計測](reading-final.json) / [指摘一覧JSON](issues.json)\n`;
fs.writeFileSync(`${out}/REPORT.md`,md);
const esc=s=>String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('"','&quot;');
const htmlTable=(heads,rows)=>`<div class="table"><table><thead><tr>${heads.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(c=>`<td>${esc(c)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
const figure=(src,label)=>{assert(fs.existsSync(`${out}/${src}`),src);return `<figure><a href="${src}"><img loading="lazy" src="${src}" alt="${esc(label)}"></a><figcaption>${esc(label)} · クリックで原寸</figcaption></figure>`;};
